export function with_provenance(entry: JsonDict): JsonDict {
  // B7: shallow copy — nested containers keep aliasing MARKETPLACE_CATALOG.
  // `dict(entry)` (not a JS spread): a non-mapping entry raises out of here.
  const out: JsonDict = pyDict(entry);
  const source = pyOr(dictGet(entry, "source"), dictGet(_ENTRY_SOURCES, dictGet(entry, "id", ""), ""));
  out["source"] = source;
  const meta = dictGet(SOURCE_REGISTRY, source, null) ?? _UNKNOWN_SOURCE;
  for (const k of Object.keys(meta)) out[k] = (meta as JsonDict)[k];
  return out;
}

