// ── catalog query (lines 561-587) ───────────────────────────────────────────

export function get_marketplace_catalog(
  category?: string | null,
  query?: string | null,
  type_filter?: string | null,
): JsonDict[] {
  let res: JsonDict[] = MARKETPLACE_CATALOG.map((item) => with_provenance(item));
  // PORT DEFECT FIX (u219-closer3): skill_registry.py:573/574/576/577/580 all
  // read `x.strip().lower()`, so the FIRST attribute lookup on a non-str filter
  // is `strip` and CPython reports "'int' object has no attribute 'strip'"
  // (measured: tmp/w219_facts_py.json cases ca#type_nonstr / ca#cat_nonstr /
  // ca#q_nonstr).  The previous body lowered first (wrong message) and, for
  // `query`, stringified with String() so no exception was raised at all.
  if (pyTruth(type_filter) && !pyIn(pyLower(pyStripAttr(type_filter)), ["all", "*"])) {
    const tLower = pyLower(pyStripAttr(type_filter));
    res = res.filter((item) => pyLower(dictGet(item, "type", "skill")) === tLower);
  }
  if (pyTruth(category) && !pyIn(pyLower(pyStripAttr(category)), ["all", "*"])) {
    const catLower = pyLower(pyStripAttr(category));
    res = res.filter((item) => pyLower(dictGet(item, "category", "")) === catLower);
  }
  if (pyTruth(query)) {
    // B9: query is NOT stripped before the truthiness test, but IS stripped for
    // the match — so "   " matches everything.
    const qLower = pyLower(pyStripAttr(query));
    const filtered: JsonDict[] = [];
    for (const item of res) {
      const text = pyLower(`${pyStr(pyOr(dictGet(item, "name"), ""))} ${pyStr(pyOr(dictGet(item, "title"), ""))} ${pyStr(pyOr(dictGet(item, "description"), ""))} ${pyJoinSpace(dictGet(item, "tags", []))}`);
      if (text.includes(qLower)) filtered.push(item);
    }
    res = filtered;
  }
  return res;
}

// ── tree hash (lines 590-607) ───────────────────────────────────────────────

export function calculate_directory_hash(dir_path: string): string {
  const h = SR_SEAMS.sha256();
  for (const triple of SR_SEAMS.walk(dir_path)) {
    const root = triple.root;
    triple.dirs.sort();
    const files = [...triple.files].sort();
    for (const f of files) {
      if (f === ".ready.json") continue;
      const fpath = ntpJoin(root, f);
      const rel = pyReplace(ntpRelpath(fpath, dir_path), "\\", "/");
      h.update(new TextEncoder().encode(rel));
      try {
        h.update(SR_SEAMS.readBytes(fpath));
      } catch {
        /* B13: path contributes, bytes do not */
      }
    }
  }
  return h.hexdigest();
}

// ── the 5-stage install (lines 610-804) ─────────────────────────────────────

export function install_marketplace_skill(
  skill_id: string,
  source_dir?: string | null,
  dest_root?: string | null,
  loader?: LoaderLike | null,
): Result<unknown> {
  // python line 617 — the function-local import is the first statement of the
  // function (see the `vetterImport` seam note): unresolvable ⇒ ModuleNotFoundError
  // escapes from HERE, never through B19's per-file arm.
  SR_SEAMS.vetterImport();
  const here = ntpDirname(ntpAbsPath(SR_SEAMS.moduleFile(), SR_SEAMS.cwd()));
  const project = ntpNormpath(ntpJoin(here, "..", ".."));

  let entry: JsonDict | null = MARKETPLACE_CATALOG.find(
    (item) => item["id"] === skill_id || item["name"] === skill_id,
  ) ?? null;

  // ── Dispatch MCP Connectors (lines 621-669) ────────────────────────
  if (entry !== null && dictGet(entry, "type") === "mcp") {
    const mcpCfg = (pyOr(dictGet(entry, "mcpConfig"), {}) ?? {}) as JsonDict;
    const serverName = dictGet(entry, "name", skill_id) as string;
    const cfgPath = ntpJoin(project, "config.json");
    let cfg: unknown = {};
    if (SR_SEAMS.isFile(cfgPath)) {
      try {
        cfg = pyJsonLoads(SR_SEAMS.readTextStrict(cfgPath));
      } catch {
        cfg = {};
      }
    }
    // B24: `cfg.setdefault(...)` on a non-dict top level raises out of the function.
    if (cfg === null || typeof cfg !== "object" || Array.isArray(cfg)) {
      throw new AttributeErrorP(`'${pyTypeName(cfg)}' object has no attribute 'setdefault'`);
    }
    const cfgObj = cfg as JsonDict;
    if (!Object.prototype.hasOwnProperty.call(cfgObj, "mcpServers")) cfgObj["mcpServers"] = {};
    const mcpServers = cfgObj["mcpServers"];
    if (mcpServers === null || typeof mcpServers !== "object") {
      throw new TypeErrorP(`'${pyTypeName(mcpServers)}' object does not support item assignment`);
    }
    (mcpServers as JsonDict)[serverName] = { ...mcpCfg };
    try {
      SR_SEAMS.writeText(cfgPath, pyJsonDumps2(cfgObj));
    } catch (e) {
      return Result.failure(`Failed to persist config.json: ${pyExcStr(e)}`);
    }

    record_mcp_provenance(serverName, entry);

    try {
      const bindings = SR_SEAMS.mcpBindings();
      const mgr = bindings.getMcpManager();
      const serverConnCfg = bindings.MCPServerConfig.from_dict(serverName, mcpCfg);
      const conn = new bindings.MCPServerConnection(serverConnCfg, bindings.getToolRegistry());
      const servers = mgr._servers as unknown;
      // B27: replaces a live connection without stopping it. python subscripts a
      // dict; the landed manager keys a Map, so both shapes are handled (D-Map).
      if (servers instanceof Map) (servers as Map<string, unknown>).set(serverName, conn);
      else (servers as JsonDict)[serverName] = conn;
      if (!serverConnCfg.disabled && pyOr(serverConnCfg.command, serverConnCfg.url)) {
        const loop = SR_SEAMS.getRunningLoop();
        if (loop === null) throw new RuntimeErrorP("no running event loop");
        SR_SEAMS.scheduleStart(conn);
      }
    } catch {
      /* B26: total swallow — installed: True either way */
    }

    return Result.success({
      name: serverName,
      type: "mcp",
      mcpConfig: mcpCfg,
      installed: true,
    });
  }

  // ── Dispatch Plugins (lines 671-708) ───────────────────────────────
  if (entry !== null && dictGet(entry, "type") === "plugin") {
    const pManifest = (pyOr(dictGet(entry, "pluginManifest"), {}) ?? {}) as JsonDict;
    const pluginName = dictGet(entry, "name", skill_id) as string;
    const pluginDir = ntpJoin(project, ".agents", "plugins", pluginName);
    SR_SEAMS.mkdirs(pluginDir);
    const manifestFile = ntpJoin(pluginDir, "plugin.json");
    try {
      SR_SEAMS.writeText(manifestFile, pyJsonDumps2(pManifest));
    } catch (e) {
      return Result.failure(`Failed to write plugin manifest: ${pyExcStr(e)}`);
    }

    const contributes = dictGet(pManifest, "contributes", {}) as unknown;
    if (contributes === null || typeof contributes !== "object" || Array.isArray(contributes)) {
      // B28: `.get("contributes", {}).get("skills", [])` on a non-dict.
      throw new AttributeErrorP(`'${pyTypeName(contributes)}' object has no attribute 'get'`);
    }
    // `.get("skills", [])` returns the stored value verbatim: a missing key yields
    // the `[]` default, but an explicit null/"abc"/[5] is returned as-is (dictGet's
    // `pyOr` coercion would wrongly replace null with []).
    const relSkillsRaw = dictGet(contributes, "skills", []);
    // Python `for rel_skill in <val>` (source line 686): None/int are not iterable,
    // a str iterates its characters, a dict its keys, a list its items.
    let relSkills: unknown[];
    if (typeof relSkillsRaw === "string") relSkills = [...relSkillsRaw];
    else if (Array.isArray(relSkillsRaw)) relSkills = relSkillsRaw;
    else if (relSkillsRaw !== null && typeof relSkillsRaw === "object") relSkills = Object.keys(relSkillsRaw as JsonDict);
    else throw new TypeErrorP(`'${pyTypeName(relSkillsRaw)}' object is not iterable`);
    for (const relSkill of relSkills) {
      // `os.path.join(plugin_dir, rel_skill)` rejects a non-str operand with this
      // exact CPython wording before any mkdir/write happens.
      if (typeof relSkill !== "string") {
        throw new TypeErrorP(`join() argument must be str, bytes, or os.PathLike object, not '${pyTypeName(relSkill)}'`);
      }
      const skDir = ntpJoin(pluginDir, relSkill);
      SR_SEAMS.mkdirs(skDir);
      const skMd = ntpJoin(skDir, "SKILL.md");
      if (!SR_SEAMS.pathExists(skMd)) {
        SR_SEAMS.writeText(
          skMd,
          `---\nname: ${ntpBasename(relSkill)}\ndescription: ${pyStr(dictGet(entry, "description", ""))}\n---\n\n# ${pyStr(dictGet(entry, "title", pluginName))}\n\n${pyStr(dictGet(entry, "description", ""))}\n`,
        );
      }
    }

    let pub: JsonDict;
    try {
      const reg = SR_SEAMS.pluginRegistry();
      const res = reg.import_plugin(pluginDir, { activate: true });
      pub = (res.ok ? res.value : {}) as JsonDict;
    } catch (e) {
      pub = { error: pyExcStr(e) };
    }

    return Result.success({
      name: pluginName,
      type: "plugin",
      installed_path: pluginDir,
      details: pub,
      installed: true,
    });
  }

  // ── Stage 1: size check (lines 710-719) ────────────────────────────
  const MAX_SIZE = 50 * 1024 * 1024;
  if (pyTruth(source_dir) && SR_SEAMS.pathExists(String(source_dir))) {
    let totalSize = 0;
    for (const triple of SR_SEAMS.walk(String(source_dir))) {
      for (const f of triple.files) totalSize += SR_SEAMS.fileSize(ntpJoin(triple.root, f));
    }
    if (totalSize > MAX_SIZE) {
      return Result.failure(`Skill package exceeds 50MB limit (${pyStr(totalSize)} bytes)`);
    }
  }

  // ── Stage 2..5 (lines 721-804) ─────────────────────────────────────
  return withTempDir("ovolve-stage-", (stageTmp) => {
    const stagingDir = ntpJoin(stageTmp, "payload");
    if (pyTruth(source_dir) && SR_SEAMS.pathExists(String(source_dir))) {
      SR_SEAMS.copyTree(String(source_dir), stagingDir);
    } else {
      if (!entry) {
        // B15: verbatim re-execution of the lookup above; entry is falsy here.
        entry = MARKETPLACE_CATALOG.find(
          (item) => item["id"] === skill_id || item["name"] === skill_id,
        ) ?? null;
      }
      if (!entry) {
        return Result.failure(`Skill '${pyStr(skill_id)}' not found in marketplace catalog`);
      }
      const rawSource = dictGet(entry, "source");
      if (rawSource === undefined) throw new KeyErrorP("source");
      if (typeof rawSource !== "string") {
        throw new AttributeErrorP(`'${pyTypeName(rawSource)}' object has no attribute 'replace'`);
      }
      const src0 = pyReplace(rawSource, "github.com/", "");
      const cloned = _clone_github(src0, ntpJoin(stageTmp, "repo"));
      if (!cloned.ok) return cloned;
      const skillPath = pyStr(pyOr(dictGet(entry, "skillPath"), ""));
      if (!pyTruth(skillPath)) {
        return Result.failure(`catalog entry '${pyStr(skill_id)}' has no skillPath`);
      }
      const src = ntpJoin(stageTmp, "repo", pyReplace(skillPath, "/", "\\"));
      if (!SR_SEAMS.isDir(src)) {
        return Result.failure(`Path '${pyStr(skillPath)}' not found in repository`);
      }
      SR_SEAMS.copyTree(src, stagingDir);
    }

    // Stage 3: mandatory skill-vetter AST scan
    const skillMd = ntpJoin(stagingDir, "SKILL.md");
    if (!SR_SEAMS.isFile(skillMd)) {
      return Result.failure("Invalid skill package: missing SKILL.md");
    }

    const filesToScan: string[] = [];
    for (const triple of SR_SEAMS.walk(stagingDir)) {
      for (const f of triple.files) {
        if (pyEndswithAny(f, [".md", ".py", ".sh", ".js", ".json", ".yaml", ".yml"])) {
          filesToScan.push(ntpJoin(triple.root, f));
        }
      }
    }

    for (const fpath of filesToScan) {
      try {
        const content = SR_SEAMS.readTextReplace(fpath);
        const res = SR_SEAMS.vetSkill(content);
        const level = (res as VetResult).level;
        if (pyIn(level, [SR_SEAMS.severityHigh, SR_SEAMS.severityExtreme])) {
          const findings = (res as VetResult).findings as unknown;
          // `res.findings[0]` (source line 760): a str subscript yields its first
          // character, a list yields its element (empty list -> IndexError); any
          // other receiver is genuinely not subscriptable.
          let worst: unknown;
          if (typeof findings === "string") {
            if (findings.length === 0) throw new IndexErrorP();
            worst = findings[0];
          } else if (Array.isArray(findings)) {
            if (findings.length === 0) throw new IndexErrorP();
            worst = findings[0];
          } else {
            throw new TypeErrorP(`'${pyTypeName(findings)}' object is not subscriptable`);
          }
          const reason = pyOr(pyAttr(worst, "reason_zh"), pyAttr(worst, "reason_en"));
          return Result.failure(
            `Security audit rejected (${severityName(dictGet(worst, "severity"))}): ${pyStr(reason)} at ${ntpBasename(fpath)}`,
          );
        }
      } catch (e) {
        // B19: an IndexError inside the rejection arm lands in this same arm.
        return Result.failure(`Security scanning failed on ${ntpBasename(fpath)}: ${pyExcStr(e)}`);
      }
    }

    // Stage 4: canonical name from SKILL.md
    let canonicalName: string = skill_id;
    for (const line of SR_SEAMS.readTextLines(skillMd)) {
      if (pyStrip(line).startsWith("name:")) {
        const rawN = pyStrip(pyStrip(pyReplace(line, "name:", "")), "\"'");
        if (pyTruth(rawN)) {
          canonicalName = rawN;
          break;
        }
      }
    }

    // Stage 5: tree hash, .ready.json, atomic move
    const treeHash = calculate_directory_hash(stagingDir);
    const readyMeta: JsonDict = {
      name: canonicalName,
      vetted: true,
      tree_hash: treeHash,
      installed_at: Math.trunc(SR_SEAMS.clock()),
      source: pyOr(source_dir, "marketplace"),
    };
    SR_SEAMS.writeText(ntpJoin(stagingDir, ".ready.json"), pyJsonDumps2(readyMeta));

    const targetRoot = pyTruth(dest_root) ? String(dest_root) : _skills_dest();
    SR_SEAMS.mkdirs(targetRoot);
    const finalDest = pathDiv(targetRoot, canonicalName);
    if (SR_SEAMS.pathExists(finalDest)) SR_SEAMS.removeTree(finalDest);

    SR_SEAMS.copyTree(stagingDir, finalDest);

    if (pyTruth(loader) && attrExists(loader, "import_skill")) {
      // B30: result discarded.
      callAttr(loader, "import_skill", [finalDest, SR_SEAMS.trustLevelVerified]);
    }

    return Result.success({
      name: canonicalName,
      installed_path: finalDest,
      tree_hash: treeHash,
      ready: readyMeta,
    });
  });
}

